sources.app.tsx:
// @name Notion database
// @background #f7f7f5
// @refresh 900
// A Notion database's rows on the frame: each row's title and up to two of
// its properties (a status, a due date, a person...), the done ones left out
// as the settings say, sorted. When the Checkbox setting names a checkbox
// property, each row has a box: a tap ticks it in Notion (tap again to take
// it back).
//
// The frame asks Notion itself (notion.ts), at the scene's refresh interval
// or when Refresh is tapped, and keeps what it read last in the scene's
// private `cache` field, so the rows stay up when Notion cannot be reached
// and a line says why.
import { notionId, plan, problemOf, readRows, readSchema, sendCheck } from './notion'
import type { Row, Schema, Settings, Val } from './notion'
import { INKS, THEMES, clockText, dayKey, listScreen, relativeDay, roundScreen, setRows, setScale, setupScreen, themeOf } from './ui'
import type { Item, Part, RowView } from './ui'

const HOUR = 3600000

// Notion's own page on a color panel: its warm white and its ink.
Object.assign(THEMES.color, {
  page: 'bg-[#f7f7f5] text-[#37352f]',
  muted: 'text-[#787774]',
  head: 'text-[#787774]',
  doneText: 'text-[#a5a29b] line-through',
  button: 'bg-white text-[#5f5e5b] active:bg-[#ebeae7]',
  step: 'bg-[#37352f] text-white',
  code: 'bg-[#ebeae7] text-[#37352f]',
})

// ---------------------------------------------------------------- what is kept

// What the scene keeps between renders, in its private `cache` field (on
// disk, so a restart shows the rows at once): the rows as read last, when,
// the data source's schema, what the settings name in it, and what went
// wrong last.
export type Cache = {
  key: string
  at: number
  rows: Row[]
  more: boolean
  schema: Schema | null
  sAt: number
  shown: { p1: string; p2: string; checkbox: string }
  notes: string[]
  err: string
  // The last read failed: the rows are the ones from `at`.
  stale: boolean
  retryAt: number
}

const flag = (value: any, otherwise: boolean) => (value === undefined || value === null || value === '' ? otherwise : value === true || value === 'true')

const settingsOf = (app): Settings & { title: string } => ({
  token: String(app.state.token || '').trim(),
  database: String(app.state.database || '').trim(),
  property1: String(app.state.property1 || '').trim(),
  property2: String(app.state.property2 || '').trim(),
  checkbox: String(app.state.checkbox || '').trim(),
  hideChecked: flag(app.state.hideChecked, true),
  hideStatus: String(app.state.hideStatus ?? 'Done').trim(),
  sortBy: String(app.state.sortBy || '').trim(),
  sortOrder: app.state.sortOrder === 'descending' ? 'descending' : 'ascending',
  title: String(app.state.title || '').trim(),
})

// A short mark of the token, so a new one reads everything again without the
// token itself being kept twice.
const mark = (text: string) => {
  let h = 5381
  for (let i = 0; i < text.length; i++) h = ((h * 33) ^ text.charCodeAt(i)) >>> 0
  return h.toString(36)
}
const keyOf = (s: Settings) =>
  [mark(s.token), notionId(s.database), s.property1, s.property2, s.checkbox, s.hideChecked, s.hideStatus, s.sortBy, s.sortOrder].join('|')

export function loadCache(app): Cache | null {
  let kept = app.state.cache
  if (typeof kept === 'string') {
    try {
      kept = kept ? JSON.parse(kept) : null
    } catch (e) {
      kept = null
    }
  }
  return kept && typeof kept === 'object' && Array.isArray(kept.rows) ? kept : null
}
const save = (cache: Cache) => frameos.setState('cache', cache)

// ---------------------------------------------------------------- talking to Notion

const short = (text: string) => (text.length > 30 ? `${text.slice(0, 29)}...` : text)

// Sends one tick (or its undo). A call that fails puts the tick back and
// says why; answers whether it went through.
function sendOne(token: string, cache: Cache, row: Row) {
  if (!row.send) return true
  delete row.send
  delete row.at
  const reply = cache.schema && cache.shown.checkbox ? sendCheck(token, cache.schema, cache.shown.checkbox, row, !!row.c) : { status: 0, error: 'no checkbox', ok: false }
  if (reply.ok) {
    if (!cache.stale) cache.err = ''
    return true
  }
  row.c = !row.c
  cache.err = problemOf(reply, `${row.c ? 'untick' : 'tick'} "${short(row.t)}"`).text
  return false
}

// Reads the rows again, and the schema when the database changed or every
// six hours (a property added or renamed).
function refresh(app, s: Settings, cache: Cache, now: number) {
  const id = notionId(s.database)
  const fail = (text: string, waitMs: number) => {
    cache.err = text
    cache.stale = true
    cache.retryAt = now + waitMs
  }
  if (!id) return fail("The Database setting holds no Notion id: paste the database's link (its ... menu, Copy link).", 15 * 60000)
  if (!cache.schema || cache.schema.src !== id || now - cache.sAt > 6 * HOUR) {
    const read = readSchema(s.token, id, [s.property1, s.property2])
    if (!read.schema) {
      const problem = problemOf(read.reply, 'read the database')
      return fail(problem.text, problem.waitMs)
    }
    cache.schema = read.schema
    cache.sAt = now
  }
  const shown = plan(cache.schema, s)
  cache.shown = { p1: shown.p1, p2: shown.p2, checkbox: shown.checkbox }
  cache.notes = shown.notes
  const read = readRows(s.token, cache.schema, s, cache.shown, app.frame.embedded ? 25 : 50)
  if (!read.rows) {
    const problem = problemOf(read.reply, 'read the rows')
    // A query Notion cannot read may be one of a schema that changed.
    if (read.reply.status === 400) cache.sAt = 0
    return fail(problem.text, problem.waitMs)
  }
  cache.rows = read.rows
  cache.more = !!read.more
  cache.at = now
  cache.err = ''
  cache.stale = false
  cache.retryAt = 0
}

// Everything a render does before it draws: the ticks still to send, then
// a new read when the last one is as old as the scene's refresh interval.
export function sync(app, now: number): Cache {
  const s = settingsOf(app)
  const key = keyOf(s)
  let cache = loadCache(app)
  if (!cache || cache.key !== key) {
    // The schema stays for the same token and database.
    const same = cache && cache.key.split('|').slice(0, 2).join('|') === key.split('|').slice(0, 2).join('|')
    cache = {
      key, at: 0, rows: [], more: false, schema: same ? cache.schema : null, sAt: same ? cache.sAt : 0,
      shown: { p1: '', p2: '', checkbox: '' }, notes: [], err: '', stale: false, retryAt: 0,
    }
  }
  const before = JSON.stringify(cache)
  // A tick of the last few seconds is the sendTicks event's to send, after
  // the picture that shows it.
  for (const row of cache.rows) if (row.send && !(now - (row.at || 0) < 5000)) sendOne(s.token, cache, row)
  const every = Math.max(60, Number(app.state.refreshInterval) || 900) * 1000
  if ((!cache.at || now - cache.at >= every - 30000) && now >= (cache.retryAt || 0)) refresh(app, s, cache, now)
  // Asked to wait less than the interval (no network, a busy Notion): wake
  // for it.
  if (cache.retryAt > now && cache.retryAt - now < every) frameos.setNextSleep(Math.ceil((cache.retryAt - now) / 1000))
  if (JSON.stringify(cache) !== before) save(cache)
  return cache
}

// ---------------------------------------------------------------- what a tap does

let current = null
let shownIds: string[] = []

const fastPanel = (app) => (app.frame.fast ?? !app.frame.paper) !== false

// A tap on a row's box: the tick shows at once, and Notion is told. On a
// screen that answers at once the frame draws the tick first and sends it
// right after, on the scene's own `sendTicks` event (onEvent below), which
// goes round the queue once so the picture of the tap comes first: a failure
// puts the tick back and draws a line saying why. On e-paper, where each
// picture costs a refresh, it is sent before the one picture that answers the
// tap. A tick the frame had no time to send goes with a render seconds later.
export function toggle(app, i: number) {
  const s = settingsOf(app)
  const cache = loadCache(app)
  const row = cache?.rows.find((each) => each.id === shownIds[i])
  if (!cache || !row || row.send || !cache.shown.checkbox) return
  row.c = !row.c
  row.send = true
  row.at = Date.now()
  if (fastPanel(app) && typeof frameos.dispatch === 'function') {
    save(cache)
    frameos.dispatch('sendTicks', { hop: 1 })
    return
  }
  sendOne(s.token, cache, row)
  save(cache)
}

// The ticks shown and not sent yet. A failure draws the rows again (the tick
// back, and the line); a success leaves the picture as it is.
export function onEvent(app, context) {
  if (context.event !== 'sendTicks') return false
  // Once round the queue first, behind the render that shows the tap.
  if (context.payload?.hop === 1) {
    frameos.dispatch('sendTicks', { hop: 2 })
    return false
  }
  const cache = loadCache(app)
  if (!cache || !cache.rows.some((row) => row.send)) return false
  const token = settingsOf(app).token
  let failed = false
  for (const row of cache.rows) if (row.send && !sendOne(token, cache, row)) failed = true
  save(cache)
  return failed
}

// Refresh: read the rows (and the schema) again now.
export function refreshNow(app) {
  const cache = loadCache(app)
  if (!cache) return
  cache.at = 0
  cache.sAt = 0
  cache.retryAt = 0
  save(cache)
}

// ---------------------------------------------------------------- what the rows say

// "8 to do, 2 done", or "12 rows".
export function tallyOf(cache: Cache) {
  const count = cache.rows.length
  const more = cache.more ? '+' : ''
  if (!cache.shown.checkbox) return count ? `${count}${more} ${count === 1 && !more ? 'row' : 'rows'}` : 'No rows'
  const done = cache.rows.filter((row) => row.c).length
  if (!count) return 'Nothing to do'
  return done ? `${count - done}${more} to do, ${done} done` : `${count - done}${more} to do`
}

// Notion's colors for a select's or a status's option: the chip's ground
// and, for a status, its dot (light mode).
const CHIP = {
  default: ['#ebeae7', '#a3a29e'], gray: ['#e3e2e0', '#91918e'], brown: ['#eee0da', '#a27763'], orange: ['#fadec9', '#d9730d'],
  yellow: ['#fdecc8', '#cb912f'], green: ['#dbeddb', '#448361'], blue: ['#d3e5ef', '#337ea9'], purple: ['#e8deee', '#9065b0'],
  pink: ['#f5e0e9', '#c14c8a'], red: ['#ffe2dd', '#d44c47'],
}
// On color e-paper a chip is a solid ink where Notion's color has one.
const INK_CHIP = {
  red: `bg-[${INKS.red}] text-white`, pink: `bg-[${INKS.red}] text-white`, green: `bg-[${INKS.green}] text-white`,
  blue: `bg-[${INKS.blue}] text-white`, purple: `bg-[${INKS.blue}] text-white`, yellow: `bg-[${INKS.yellow}] text-black`,
  orange: `bg-[${INKS.yellow}] text-black`,
}

function chipPart(t, text: string, color: string, status: boolean): Part {
  if (t === THEMES.color) {
    const [ground, dot] = CHIP[color.replace(/_background$/, '')] || CHIP.default
    return { text, chip: `bg-[${ground}] text-[#32302c]`, dot: status ? dot : undefined }
  }
  if (t === THEMES.inks && INK_CHIP[color]) return { text, chip: INK_CHIP[color] }
  return { text, chip: 'border border-black' }
}

function partsOf(t, value: Val | null | undefined, done: boolean, today: string, now: number, twelve: boolean): Part[] {
  if (!value) return []
  switch (value.k) {
    case 'chip':
      return [chipPart(t, value.t, value.c, !!value.s)]
    case 'chips':
      return value.l.map((option) => chipPart(t, option.t, option.c, false))
    case 'date': {
      const late = !done && (value.ms ? value.ms < now : value.d < today)
      const time = value.ms ? ` ${clockText(value.ms, twelve)}` : ''
      return [{ text: `${relativeDay(value.d, today)}${time}`, icon: 'calendar', cls: late ? t.late : t.muted }]
    }
    case 'check':
      return value.v ? [{ text: value.n, icon: 'check' }] : []
    case 'text':
      if (value.n === '@') return [{ text: value.t, icon: 'person' }]
      if (value.n === 'link') return [{ text: value.t, icon: 'link' }]
      return [{ text: value.n ? `${value.n}: ${value.t}` : value.t }]
  }
  return []
}

export function viewOf(app, cache: Cache, now: number) {
  const t = themeOf(app)
  const twelve = app.state.clock === '12'
  const today = dayKey(now)
  const ring = cache.shown.checkbox
    ? t === THEMES.color
      ? { color: '#2383e2', fill: '#ffffff', width: 2, square: true }
      : { color: t === THEMES.inks ? INKS.blue : '#000000', fill: '#ffffff', width: 3, square: true }
    : null
  const items: Item[] = []
  const rows: RowView[] = []
  const ids: string[] = []
  for (const row of cache.rows) {
    const done = !!row.c
    const parts = [...partsOf(t, row.a, done, today, now, twelve), ...partsOf(t, row.b, done, today, now, twelve)]
    rows.push({ key: row.id, text: row.t, done, ring, parts })
    ids.push(row.id)
    items.push({ row: rows.length - 1 })
  }
  return { t, items, rows, ids }
}

// ---------------------------------------------------------------- the picture

const SETUP = [
  {
    head: 'Make a connection',
    text: "A new connection in Notion's developer portal, with an API token. Copy its token into the scene's Integration token.",
    code: 'notion.so/profile/integrations',
  },
  { head: 'Share the database with it', text: 'Open the database in Notion: its ... menu, Connections, and add your connection.' },
  { head: "Paste the database's link", text: "Its ... menu, Copy link, into the scene's Database setting. Then name the properties to show." },
]

export function get(app, context) {
  current = app
  const round = context?.round === true
  const W = context?.imageWidth ?? app.frame.width
  const H = context?.imageHeight ?? app.frame.height
  const side = Math.min(W, H)
  setScale(!round && side >= 900 ? Math.min(3, Math.floor((side / 480) * 2) / 2) : 1)
  const t = themeOf(app)
  const s = settingsOf(app)
  if (!s.token || !s.database) {
    return setupScreen(t, W, H, round, 'database', 'Connect a Notion database', 'This scene shows the rows of a Notion database and needs a connection to read it.', SETUP)
  }
  const now = Date.now()
  const cache = sync(app, now)
  if (!cache.at && cache.err) return setupScreen(t, W, H, round, 'alert', 'Could not read the database', cache.err, SETUP)
  const view = viewOf(app, cache, now)
  shownIds = view.ids
  setRows(view.rows, (i) => toggle(current, i))
  const twelve = app.state.clock === '12'
  const problem = cache.err
    ? cache.stale && cache.at ? `${cache.err} Showing the rows from ${clockText(cache.at, twelve)}.` : cache.err
    : cache.notes.length ? `${cache.notes.join('. ')}: check the scene's settings.` : ''
  const screen = {
    t: view.t,
    title: s.title || cache.schema?.title || 'Notion',
    tally: tallyOf(cache),
    updated: cache.at ? clockText(cache.at, twelve) : '',
    problem,
    items: view.items,
    empty: cache.shown.checkbox && s.hideChecked ? 'Everything is done.' : 'No rows to show.',
    endNote: cache.more ? 'More rows in Notion' : '',
    onRefresh: () => refreshNow(current),
  }
  return round ? roundScreen(screen, W, H) : listScreen(screen, W, H)
}

sources.notion.ts:
// Notion's API (developers.notion.com), version 2025-09-03, the calls this
// scene makes:
//   GET   /v1/databases/{id}                 a database: its title and its data sources [{id, name}]
//   GET   /v1/data_sources/{id}              a data source: its title and its properties (the schema)
//   POST  /v1/data_sources/{id}/query        a page of its rows, filtered and sorted
//   PATCH /v1/pages/{id}                     tick a row's checkbox
// Since 2025-09-03 a database holds one or more data sources and the rows are
// queried from a data source: a database's id is resolved to its first one.
// A data source's own id (Notion's "Copy data source ID") works too.
// filter_properties keeps each row to the properties drawn, and the query
// asks for one small page.

export const API = 'https://api.notion.com/v1'
export const VERSION = '2025-09-03'

export type Reply = { status: number; body?: string; error?: string; headers?: Record<string, string> }

export function call(token: string, method: string, path: string, body?: any): Reply {
  const headers: Record<string, string> = { Authorization: `Bearer ${token}`, 'Notion-Version': VERSION, Accept: 'application/json' }
  if (body !== undefined) headers['Content-Type'] = 'application/json'
  const reply = frameos.httpRequest(API + path, {
    method,
    headers,
    body: body === undefined ? undefined : JSON.stringify(body),
    timeoutMs: 15000,
  })
  return { status: reply.status || 0, body: reply.body, error: reply.error, headers: reply.headers }
}

export const ok = (reply: Reply) => reply.status >= 200 && reply.status < 300
const parse = (reply: Reply) => {
  try {
    return JSON.parse(reply.body || 'null')
  } catch (e) {
    return null
  }
}

// ---------------------------------------------------------------- ids

const dashed = (hex: string) => `${hex.slice(0, 8)}-${hex.slice(8, 12)}-${hex.slice(12, 16)}-${hex.slice(16, 20)}-${hex.slice(20)}`.toLowerCase()

// The Database setting: an id (32 hex digits, dashed or not) or a link to the
// database (https://www.notion.so/team/Tasks-248104cd477e80fdb757e945d38000bd?v=...,
// https://app.notion.com/p/...). The id is the last one in the path: the
// ?v= after it is a view's, and a ?p= a page opened over it.
export function notionId(text: string) {
  const path = String(text || '').trim().split(/[?#]/)[0]
  const uuids = path.match(/[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}/gi)
  if (uuids) return uuids[uuids.length - 1].toLowerCase()
  const runs = path.match(/(?:^|[^0-9a-f])([0-9a-f]{32})(?![0-9a-f])/gi)
  if (!runs) return ''
  const last = runs[runs.length - 1]
  return dashed(last.slice(last.length - 32))
}

// ---------------------------------------------------------------- the schema

// A property as the scene keeps it: its id, its type, and for a status or a
// select the colors of its options (and a status's groups, by name).
export type Prop = { id: string; type: string; opts?: Record<string, string>; groups?: Record<string, string[]> }
export type Schema = { ds: string; src: string; title: string; props: Record<string, Prop>; titleName: string }

export const plain = (rich: any) => (Array.isArray(rich) ? rich.map((part) => String(part?.plain_text ?? '')).join('') : '')

// A data source's properties, cut down: every one's id and type, and the
// options of the ones the scene reads by their values.
export function slimSchema(source: any, wanted: string[]): { props: Record<string, Prop>; titleName: string } {
  const props: Record<string, Prop> = {}
  let titleName = ''
  const all = source && source.properties && typeof source.properties === 'object' ? source.properties : {}
  for (const name of Object.keys(all)) {
    const prop = all[name] || {}
    const kept: Prop = { id: String(prop.id ?? ''), type: String(prop.type ?? '') }
    if (kept.type === 'title') titleName = name
    const choices = prop[kept.type]
    if ((kept.type === 'status' || kept.type === 'select') && (wanted.includes(name) || kept.type === 'status') && choices) {
      kept.opts = {}
      for (const option of choices.options || []) kept.opts[String(option.name)] = String(option.color || 'default')
      if (kept.type === 'status' && Array.isArray(choices.groups)) {
        kept.groups = {}
        const byId = {}
        for (const option of choices.options || []) byId[option.id] = String(option.name)
        for (const group of choices.groups) kept.groups[String(group.name)] = (group.option_ids || []).map((id) => byId[id]).filter(Boolean)
      }
    }
    props[name] = kept
  }
  return { props, titleName }
}

// A property by the name someone typed: exactly, else in any case, else the
// one property whose name starts with it ("Due" finds "Due date").
export function findProp(props: Record<string, Prop>, name: string): string {
  const wanted = String(name || '').trim()
  if (!wanted) return ''
  if (props[wanted]) return wanted
  const lower = wanted.toLowerCase()
  const names = Object.keys(props)
  const same = names.find((each) => each.toLowerCase() === lower)
  if (same) return same
  const starting = names.filter((each) => each.toLowerCase().startsWith(lower))
  return starting.length === 1 ? starting[0] : ''
}

// Finds the data source behind the Database setting: a database's first,
// or the data source itself when the id is one.
export function readSchema(token: string, id: string, wanted: string[]): { schema?: Schema; reply: Reply } {
  let dsId = id
  let title = ''
  const database = call(token, 'GET', `/databases/${id}`)
  if (ok(database)) {
    const data = parse(database)
    const sources = data && Array.isArray(data.data_sources) ? data.data_sources : []
    if (!sources.length) return { reply: { status: 404, body: JSON.stringify({ code: 'object_not_found', message: 'This database has no data source.' }) } }
    dsId = String(sources[0].id)
    // A database of several sources shows its first, by that one's name.
    title = sources.length > 1 && sources[0].name ? String(sources[0].name) : plain(data.title)
  } else if (database.status !== 404 && database.status !== 400) {
    // A refused token, a busy Notion, no network: asking again as a data
    // source would get the same.
    return { reply: database }
  }
  const source = call(token, 'GET', `/data_sources/${dsId}`)
  if (!ok(source)) {
    if (ok(database)) return { reply: source }
    // Neither a database nor a data source by that id: Notion's "not found"
    // says it best.
    return { reply: source.status === 404 || database.status !== 404 ? source : database }
  }
  const data = parse(source)
  if (!data) return { reply: { status: 502, error: 'an answer that is no JSON' } }
  const slim = slimSchema(data, wanted)
  return { schema: { ds: dsId, src: id, title: title || plain(data.title), props: slim.props, titleName: slim.titleName }, reply: source }
}

// ---------------------------------------------------------------- the query

export type Settings = {
  token: string
  database: string
  property1: string
  property2: string
  checkbox: string
  hideChecked: boolean
  hideStatus: string
  sortBy: string
  sortOrder: string
}

// What the settings name, checked against the schema: the properties to
// draw, the checkbox, and the notes for names that are not there.
export function plan(schema: Schema, s: Settings) {
  const notes: string[] = []
  const pick = (name: string, what: string, types?: string[]) => {
    if (!String(name || '').trim()) return ''
    const found = findProp(schema.props, name)
    if (!found) notes.push(`No property called "${name}"`)
    else if (types && !types.includes(schema.props[found].type)) {
      notes.push(`"${found}" is no ${what}`)
      return ''
    }
    return found
  }
  const p1 = pick(s.property1, '')
  const p2 = pick(s.property2, '')
  const checkbox = pick(s.checkbox, 'checkbox', ['checkbox'])
  return { p1, p2, checkbox, notes }
}

// The query's body: one small page, the rows that are done left out, sorted.
export function queryBody(schema: Schema, s: Settings, shown: { p1: string; p2: string; checkbox: string }, size: number) {
  const body: any = { page_size: size }
  const conditions: any[] = []
  if (shown.checkbox && s.hideChecked) conditions.push({ property: shown.checkbox, checkbox: { equals: false } })
  // Hide rows with status: the status property's (else a select's that is
  // shown), each value one that is there, as an option or a group.
  const hide = String(s.hideStatus || '').split(',').map((v) => v.trim()).filter(Boolean)
  if (hide.length) {
    const names = Object.keys(schema.props)
    const statusName = names.find((n) => schema.props[n].type === 'status') ||
      [shown.p1, shown.p2].find((n) => n && schema.props[n].type === 'select') || ''
    const prop = statusName ? schema.props[statusName] : null
    if (prop) {
      const kind = prop.type
      for (const value of hide) {
        const option = Object.keys(prop.opts || {}).find((o) => o.toLowerCase() === value.toLowerCase())
        const group = kind === 'status' ? Object.keys(prop.groups || {}).find((g) => g.toLowerCase() === value.toLowerCase()) : undefined
        if (option) conditions.push({ property: statusName, [kind]: { does_not_equal: option } })
        else if (group) for (const each of prop.groups[group]) conditions.push({ property: statusName, [kind]: { does_not_equal: each } })
      }
    }
  }
  if (conditions.length === 1) body.filter = conditions[0]
  else if (conditions.length > 1) body.filter = { and: conditions.slice(0, 20) }
  // Sort by: a property's name, "created" or "edited"; left empty, the date
  // shown (soonest first), else the newest row first.
  const by = String(s.sortBy || '').trim()
  const direction = s.sortOrder === 'descending' ? 'descending' : 'ascending'
  const sortProp = by ? findProp(schema.props, by) : ''
  if (sortProp) body.sorts = [{ property: sortProp, direction }]
  else if (/^created/i.test(by)) body.sorts = [{ timestamp: 'created_time', direction }]
  else if (/^(last )?edited/i.test(by)) body.sorts = [{ timestamp: 'last_edited_time', direction }]
  else {
    const date = [shown.p1, shown.p2].find((n) => n && schema.props[n].type === 'date')
    body.sorts = date ? [{ property: date, direction: 'ascending' }] : [{ timestamp: 'created_time', direction: 'descending' }]
  }
  return body
}

// The query's address: filter_properties names each property a row needs
// (their ids come URL-encoded from Notion already), the title always.
export function queryPath(schema: Schema, shown: { p1: string; p2: string; checkbox: string }) {
  const ids = ['title']
  for (const name of [shown.p1, shown.p2, shown.checkbox]) {
    const id = name ? schema.props[name].id : ''
    if (id && !ids.includes(id)) ids.push(id)
  }
  return `/data_sources/${schema.ds}/query?${ids.map((id) => `filter_properties=${id}`).join('&')}`
}

// ---------------------------------------------------------------- the rows

// A value as a row draws it: a chip (a status, s, or a select, with its color),
// chips, a date (its day, and its time when it has one), text, or a tick.
export type Val =
  | { k: 'chip'; t: string; c: string; s?: number }
  | { k: 'chips'; l: { t: string; c: string }[] }
  | { k: 'date'; d: string; ms: number }
  | { k: 'text'; t: string; n?: string }
  | { k: 'check'; v: boolean; n: string }

const pad2 = (n: number) => String(n).padStart(2, '0')
const dayOfMs = (ms: number) => {
  const d = new Date(ms)
  return `${d.getFullYear()}-${pad2(d.getMonth() + 1)}-${pad2(d.getDate())}`
}

// A Notion date's start: "2026-11-28" (a day), or a moment
// "2026-11-28T09:00:00.000+01:00" ("Z", or no offset: the frame's clock).
export function readDate(start: any): { d: string; ms: number } | null {
  const m = /^(\d{4})-(\d\d)-(\d\d)(?:T(\d\d):(\d\d)(?::(\d\d))?(?:\.\d+)?(Z|[+-]\d\d:?\d\d)?)?$/.exec(String(start || ''))
  if (!m) return null
  if (m[4] === undefined) return { d: `${m[1]}-${m[2]}-${m[3]}`, ms: 0 }
  const parts = [Number(m[1]), Number(m[2]) - 1, Number(m[3]), Number(m[4]), Number(m[5]), Number(m[6] || 0)] as const
  let ms: number
  if (!m[7]) ms = new Date(parts[0], parts[1], parts[2], parts[3], parts[4], parts[5]).getTime()
  else {
    ms = Date.UTC(parts[0], parts[1], parts[2], parts[3], parts[4], parts[5])
    const off = /([+-])(\d\d):?(\d\d)/.exec(m[7])
    if (off) ms -= (off[1] === '-' ? -1 : 1) * (Number(off[2]) * 60 + Number(off[3])) * 60000
  }
  return { d: dayOfMs(ms), ms }
}

const short = (text: string, most = 60) => (text.length > most ? `${text.slice(0, most - 1)}...` : text)
const names = (people: any) => (Array.isArray(people) ? people.map((p) => p?.name).filter(Boolean).join(', ') : '')
const hostOf = (url: string) => String(url || '').replace(/^https?:\/\//i, '').replace(/^www\./i, '').split(/[/?#]/)[0]

// One property's value on a page, as a row draws it; null for an empty one.
export function readValue(name: string, value: any): Val | null {
  if (!value || typeof value !== 'object') return null
  const type = value.type
  const v = value[type]
  switch (type) {
    case 'status':
      return v && v.name ? { k: 'chip', t: short(String(v.name), 24), c: String(v.color || 'default'), s: 1 } : null
    case 'select':
      return v && v.name ? { k: 'chip', t: short(String(v.name), 24), c: String(v.color || 'default') } : null
    case 'multi_select':
      return Array.isArray(v) && v.length ? { k: 'chips', l: v.slice(0, 3).map((o) => ({ t: short(String(o.name), 18), c: String(o.color || 'default') })) } : null
    case 'date': {
      const date = v ? readDate(v.start) : null
      return date ? { k: 'date', d: date.d, ms: date.ms } : null
    }
    case 'created_time':
    case 'last_edited_time': {
      const date = readDate(v)
      return date ? { k: 'date', d: date.d, ms: date.ms } : null
    }
    case 'checkbox':
      return { k: 'check', v: !!v, n: name }
    case 'number':
      return typeof v === 'number' ? { k: 'text', t: String(Math.round(v * 100) / 100), n: name } : null
    case 'title':
    case 'rich_text': {
      const text = plain(v).replace(/\s+/g, ' ').trim()
      return text ? { k: 'text', t: short(text) } : null
    }
    case 'people':
    case 'created_by':
    case 'last_edited_by': {
      const who = type === 'people' ? names(v) : v?.name || ''
      return who ? { k: 'text', t: short(who, 40), n: '@' } : null
    }
    case 'url':
      return v ? { k: 'text', t: short(hostOf(v), 40), n: 'link' } : null
    case 'email':
    case 'phone_number':
      return v ? { k: 'text', t: short(String(v), 40) } : null
    case 'unique_id':
      return v && v.number !== null && v.number !== undefined ? { k: 'text', t: v.prefix ? `${v.prefix}-${v.number}` : String(v.number) } : null
    case 'formula':
      if (!v) return null
      if (v.type === 'date') return readValue(name, { type: 'date', date: v.date })
      if (v.type === 'boolean') return { k: 'check', v: !!v.boolean, n: name }
      if (v.type === 'number') return readValue(name, { type: 'number', number: v.number })
      return v.string ? { k: 'text', t: short(String(v.string)) } : null
    case 'rollup':
      if (!v) return null
      if (v.type === 'number') return readValue(name, { type: 'number', number: v.number })
      if (v.type === 'date') return readValue(name, { type: 'date', date: v.date })
      if (v.type === 'array' && Array.isArray(v.array)) return v.array.length ? { k: 'text', t: `${v.array.length}`, n: name } : null
      return null
    case 'relation':
      return Array.isArray(v) && v.length ? { k: 'text', t: `${v.length}${value.has_more ? '+' : ''}`, n: name } : null
    case 'files':
      return Array.isArray(v) && v.length ? { k: 'text', t: `${v.length}`, n: name } : null
    default:
      return null
  }
}

// A row as the scene keeps it: its page's id, its title, its tick, and the
// two values drawn. send and at are the frame's own: a tick still to send,
// and when it was tapped.
export type Row = { id: string; t: string; c?: boolean; a?: Val | null; b?: Val | null; send?: boolean; at?: number }

export function slimRow(page: any, schema: Schema, shown: { p1: string; p2: string; checkbox: string }): Row {
  const props = page && page.properties ? page.properties : {}
  const title = plain(props[schema.titleName]?.title).replace(/\s+/g, ' ').trim()
  const row: Row = { id: String(page.id), t: short(title || 'Untitled', 120) }
  if (shown.checkbox) row.c = props[shown.checkbox]?.checkbox === true
  if (shown.p1) row.a = readValue(shown.p1, props[shown.p1])
  if (shown.p2) row.b = readValue(shown.p2, props[shown.p2])
  return row
}

// One page of rows.
export function readRows(token: string, schema: Schema, s: Settings, shown, size: number): { rows?: Row[]; more?: boolean; reply: Reply } {
  const reply = call(token, 'POST', queryPath(schema, shown), queryBody(schema, s, shown, size))
  if (!ok(reply)) return { reply }
  const data = parse(reply)
  if (!data) return { reply: { status: 502, error: 'an answer that is no JSON' } }
  const results = Array.isArray(data.results) ? data.results : []
  const rows = results.filter((page) => page && page.object !== 'data_source').slice(0, size).map((page) => slimRow(page, schema, shown))
  return { rows, more: !!data.has_more, reply }
}

// Ticks a row's checkbox, or takes the tick back. The answer is the page,
// kept to that one property.
export function sendCheck(token: string, schema: Schema, checkbox: string, row: Row, value: boolean): Reply & { ok: boolean } {
  const id = schema.props[checkbox]?.id || ''
  const reply = call(token, 'PATCH', `/pages/${row.id}${id ? `?filter_properties=${id}` : ''}`, { properties: { [checkbox]: { checkbox: value } } })
  return { ...reply, ok: ok(reply) }
}

// ---------------------------------------------------------------- what went wrong

// A reply that is no success, as a line for the screen, and how long to
// leave Notion alone before asking again.
export function problemOf(reply: Reply, doing: string): { text: string; waitMs: number } {
  const data = reply.body ? parse(reply) : null
  const code = data && data.code ? String(data.code) : ''
  const message = data && data.message ? String(data.message) : ''
  const retryAfter = Number(reply.headers?.['retry-after'] || data?.additional_data?.retry_after || 0)
  const status = reply.status
  if (!status) {
    const why = reply.error || 'no answer'
    if (why.startsWith('Local network access is off')) return { text: why, waitMs: 120000 }
    return { text: `Could not reach Notion to ${doing}: ${why}.`, waitMs: 120000 }
  }
  if (status === 401) return { text: "Notion refused the integration token. Check the scene's Integration token setting.", waitMs: 15 * 60000 }
  if (status === 404 || code === 'object_not_found') {
    return {
      text: "Notion finds no such database for this token: check the Database setting, and share the database with your connection (its ... menu, Connections).",
      waitMs: 15 * 60000,
    }
  }
  if (status === 403) {
    return { text: `Notion would not let this connection ${doing}: give it the capability in its settings (${short(message || code, 80)}).`, waitMs: 15 * 60000 }
  }
  if (status === 429) {
    const wait = Math.max(30, retryAfter)
    return { text: `Notion asks to slow down. Trying again in ${Math.ceil(wait / 60)} min.`, waitMs: wait * 1000 }
  }
  if (status === 400) return { text: `Notion could not ${doing}: ${short(message || code || 'bad request', 140)}`, waitMs: 15 * 60000 }
  return { text: `Notion had trouble (HTTP ${status}) and could not ${doing}.`, waitMs: Math.max(120, retryAfter) * 1000 }
}

