  const real = Date.now
  Date.now = () => when
  try {
    return run()
  } finally {
    Date.now = real
  }
}

// A Notion that answers the database, the data source, the query and the
// writes, and keeps every request it was sent.
function notion(options: { database?: any; source?: any; query?: any; patch?: any } = {}) {
  return mock.httpRequest((url: string) => {
    if (url.includes('/databases/')) return options.database ?? mock.json(DATABASE)
    if (/\/data_sources\/[^/?]+\/query/.test(url)) return options.query ?? mock.json(list(PAGES))
    if (url.includes('/data_sources/')) return options.source ?? mock.json(SOURCE)
    if (url.includes('/pages/')) return options.patch ?? mock.json(PAGES[0])
    return mock.response(400, error(400, 'invalid_request_url', 'Invalid request URL.'))
  })
}

