    expect(queryBody(schema, settings(), shown, 25)).toEqual({
      page_size: 25,
      filter: { and: [{ property: 'In stock', checkbox: { equals: false } }, { property: 'Status', status: { does_not_equal: 'Done' } }] },
      sorts: [{ property: 'Due date', direction: 'ascending' }],
    })
  })

  it('takes a whole status group, and ignores a status that is not there', () => {
    const s = settings({ hideChecked: false, hideStatus: 'complete, Archived' })
    expect(queryBody(schema, s, plan(schema, s), 25).filter).toEqual({
      and: [{ property: 'Status', status: { does_not_equal: 'Done' } }, { property: 'Status', status: { does_not_equal: "Won't do" } }],
    })
    const none = settings({ hideChecked: false, hideStatus: '' })
    expect(queryBody(schema, none, plan(schema, none), 25).filter).toBeUndefined()
  })

  it('sorts by a property, or by when rows were made or changed', () => {
    const byStatus = settings({ sortBy: 'status', sortOrder: 'descending' })
    expect(queryBody(schema, byStatus, plan(schema, byStatus), 25).sorts).toEqual([{ property: 'Status', direction: 'descending' }])
    const edited = settings({ sortBy: 'edited', sortOrder: 'descending' })
    expect(queryBody(schema, edited, plan(schema, edited), 25).sorts).toEqual([{ timestamp: 'last_edited_time', direction: 'descending' }])
    const plainRows = settings({ property1: 'Owner', property2: '' })
    expect(queryBody(schema, plainRows, plan(schema, plainRows), 25).sorts).toEqual([{ timestamp: 'created_time', direction: 'descending' }])
  })

  it('asks only for the properties a row draws, by their ids as Notion wrote them', () => {
    expect(queryPath(schema, plan(schema, settings()))).toBe(`/data_sources/${DS}/query?filter_properties=title&filter_properties=Z%3ClH&filter_properties=M%3BBw&filter_properties=fk%5EY`)
  })

  it('finds a property by the start of its name, and says which names are not there', () => {
    expect(plan(schema, settings({ property1: 'status', property2: 'Due' }))).toMatchObject({ p1: 'Status', p2: 'Due date', notes: [] })
    const shown = plan(schema, settings({ property2: 'Deadline', checkbox: 'Status' }))
    expect(shown.notes).toEqual(['No property called "Deadline"', '"Status" is no checkbox'])
    expect(shown.checkbox).toBe('')
  })
})

describe('a render', () => {
  it('finds the data source of the database, then asks for a page of rows', () => {
    const http = notion()
    const app = appWith()
    at(NOW, () => get(app, makeContext()))
    expect(http.calls.map((call) => `${call[1].method} ${call[0].split('?')[0]}`)).toEqual([
      `GET https://api.notion.com/v1/databases/${DB}`,
      `GET https://api.notion.com/v1/data_sources/${DS}`,
      `POST https://api.notion.com/v1/data_sources/${DS}/query`,
    ])
    const [, request] = http.calls[2]
    expect(request.headers).toMatchObject({ Authorization: `Bearer ${TOKEN}`, 'Notion-Version': '2025-09-03', 'Content-Type': 'application/json' })
    expect(JSON.parse(request.body).page_size).toBe(50)
    const cache = loadCache(app)
    expect(cache.schema.title).toBe('Launch tasks')
    expect(cache.rows).toEqual([
      { id: 'be633bf1-dfa0-436d-b259-571129a590e5', t: 'Bug bash', c: false, a: { k: 'chip', t: 'Not started', c: 'default', s: 1 }, b: { k: 'date', d: '2023-02-23', ms: 0 } },
      {
        id: 'be633bf1-dfa0-436d-b259-571129a590e6', t: 'Write the launch post', c: false, a: { k: 'chip', t: 'In progress', c: 'blue', s: 1 },
        b: { k: 'date', d: '2026-11-28', ms: Date.UTC(2026, 10, 28, 8, 0, 0) },
      },
    ])
    expect(tallyOf(cache)).toBe('2 to do')
  })

  it('takes a data source\'s own id', () => {
    const http = notion({ database: mock.response(404, error(404, 'object_not_found', `Could not find database with ID: ${DS}.`)) })
    const app = appWith({ database: DS })
    at(NOW, () => get(app, makeContext()))
    expect(http.calls[1][0]).toBe(`https://api.notion.com/v1/data_sources/${DS}`)
    expect(http.calls[2][0]).toContain(`/data_sources/${DS}/query?`)
    expect(loadCache(app).rows).toHaveLength(2)
  })

  it('asks for less on an ESP32, and reads the schema again only every few hours', () => {
    const http = notion()
    const app = appWith({ refreshInterval: 900 }, { embedded: true })
    at(NOW, () => get(app, makeContext()))
    expect(JSON.parse(http.calls[2][1].body).page_size).toBe(25)
    at(NOW + 5 * MINUTE, () => get(app, makeContext()))
    expect(http.calls).toHaveLength(3)
    at(NOW + 15 * MINUTE, () => get(app, makeContext()))
    expect(http.calls).toHaveLength(4)
    expect(http.calls[3][0]).toContain('/query?')
  })

  it('says when there are more rows than a page', () => {
    notion({ query: mock.json(list(PAGES, true)) })
    const app = appWith({ checkbox: '' })
    at(NOW, () => get(app, makeContext()))
    expect(tallyOf(loadCache(app))).toBe('2+ rows')
  })

  it('marks a date that has passed on a row still to do', () => {
    notion()
    const app = appWith()
    at(NOW, () => get(app, makeContext()))
    const view = viewOf(app, loadCache(app), NOW)
    expect(view.rows[0].parts[1]).toMatchObject({ text: '23 Feb 2023', cls: 'text-[#d1453b]' })
    expect(view.rows[1].parts[1]).toMatchObject({ text: 'Today 9:00', cls: 'text-[#d1453b]' })
    expect(view.rows[0].ring).toMatchObject({ square: true })
  })
})

describe('when something goes wrong', () => {
  it('says the database is not shared with the connection', () => {
    const notFound = mock.response(404, error(404, 'object_not_found', `Could not find database with ID: ${DB}. Make sure the relevant pages and databases are shared with your connection "Frame".`))
    notion({ database: notFound, source: mock.response(404, error(404, 'object_not_found', `Could not find data_source with ID: ${DB}.`)) })
    const app = appWith()
    at(NOW, () => get(app, makeContext()))
    expect(loadCache(app).err).toContain('share the database with your connection')
    expect(loadCache(app).rows).toHaveLength(0)
  })

  it('says the token was refused, and keeps the rows it had', () => {
    notion()
    const app = appWith()
    at(NOW, () => get(app, makeContext()))
    const http = notion({ query: mock.response(401, { ...error(401, 'unauthorized', 'API token is invalid.'), additional_data: { reason: 'token_invalid' } }) })
    at(NOW + 20 * MINUTE, () => get(app, makeContext()))
    const cache = loadCache(app)
    expect(http.calls).toHaveLength(1)
    expect(cache.err).toBe("Notion refused the integration token. Check the scene's Integration token setting.")
    expect(cache.stale).toBe(true)
    expect(cache.rows).toHaveLength(2)
    expect(cache.at).toBe(NOW)
  })

  it('waits as long as Notion asks when it is rate limited', () => {
    notion()
    const app = appWith()
    at(NOW, () => get(app, makeContext()))
    notion({ query: mock.response(429, error(429, 'rate_limited', 'You have been rate limited. Please try again later.'), { headers: { 'retry-after': '120' } }) })
    at(NOW + 20 * MINUTE, () => get(app, makeContext()))
    expect(loadCache(app).err).toBe('Notion asks to slow down. Trying again in 2 min.')
    expect(app.nextSleep).toBe(120)
  })

  it('tries again in two minutes when the network is down', () => {
    notion()
    const app = appWith()
    at(NOW, () => get(app, makeContext()))
    notion({ query: { status: 0, error: 'Connection timed out' } })
    at(NOW + 20 * MINUTE, () => get(app, makeContext()))
    expect(loadCache(app).err).toBe('Could not reach Notion to read the rows: Connection timed out.')
    expect(app.nextSleep).toBe(120)
  })

  it('reads the schema again after a query Notion could not read', () => {
    notion()
    const app = appWith()
    at(NOW, () => get(app, makeContext()))
    notion({ query: mock.response(400, error(400, 'validation_error', 'Could not find property with name or id: Due date')) })
    at(NOW + 20 * MINUTE, () => get(app, makeContext()))
    expect(loadCache(app).err).toBe('Notion could not read the rows: Could not find property with name or id: Due date')
    expect(loadCache(app).sAt).toBe(0)
  })
})

describe('ticking a row', () => {
  const ready = (frame = {}) => {
    const app = appWith({}, frame)
    notion()
    at(NOW, () => get(app, makeContext()))
    return app
  }

  it('shows the tick at once and sends it right after', () => {
    const app = ready({ fast: true })
    const dispatch = mock.dispatch(() => undefined)
    const http = notion()
    at(NOW, () => toggle(app, 0))
    expect(loadCache(app).rows[0]).toMatchObject({ c: true, send: true })
    expect(dispatch).toHaveBeenCalledWith('sendTicks', { hop: 1 })
    at(NOW + 50, () => get(app, makeContext()))
    expect(http.calls).toHaveLength(0)
    expect(at(NOW + 60, () => onEvent(app, makeContext({ event: 'sendTicks', payload: { hop: 1 }, hasImage: false })))).toBe(false)
    expect(dispatch).toHaveBeenLastCalledWith('sendTicks', { hop: 2 })
    expect(at(NOW + 100, () => onEvent(app, makeContext({ event: 'sendTicks', payload: { hop: 2 }, hasImage: false })))).toBe(false)
    const [url, request] = http.calls[0]
    expect(url).toBe('https://api.notion.com/v1/pages/be633bf1-dfa0-436d-b259-571129a590e5?filter_properties=fk%5EY')
    expect(request.method).toBe('PATCH')
    expect(JSON.parse(request.body)).toEqual({ properties: { 'In stock': { checkbox: true } } })
    expect(loadCache(app).rows[0].c).toBe(true)
    expect(loadCache(app).rows[0].send).toBeUndefined()
    expect(tallyOf(loadCache(app))).toBe('1 to do, 1 done')
  })

  it('puts the tick back when the connection may not change pages', () => {
    const app = ready({ fast: true })
    mock.dispatch(() => undefined)
    at(NOW, () => toggle(app, 0))
    notion({ patch: mock.response(403, error(403, 'restricted_resource', 'API token does not have access to this resource.')) })
    expect(at(NOW + 100, () => onEvent(app, makeContext({ event: 'sendTicks', payload: { hop: 2 }, hasImage: false })))).toBe(true)
    const cache = loadCache(app)
    expect(cache.rows[0].c).toBe(false)
    expect(cache.err).toBe('Notion would not let this connection tick "Bug bash": give it the capability in its settings (API token does not have access to this resource.).')
  })

  it('sends it before the one picture on e-paper, and takes it back on a second tap', () => {
    const app = ready({ fast: false, paper: true })
    const http = notion()
    at(NOW, () => toggle(app, 0))
    expect(JSON.parse(http.calls[0][1].body)).toEqual({ properties: { 'In stock': { checkbox: true } } })
    at(NOW + 1000, () => toggle(app, 0))
    expect(JSON.parse(http.calls[1][1].body)).toEqual({ properties: { 'In stock': { checkbox: false } } })
    expect(loadCache(app).rows[0].c).toBe(false)
  })

  it('has no box without a checkbox property', () => {
    notion()
    const app = appWith({ checkbox: '' })
    at(NOW, () => get(app, makeContext()))
    expect(viewOf(app, loadCache(app), NOW).rows[0].ring).toBeNull()
    const http = notion()
    at(NOW, () => toggle(app, 0))
    expect(http.calls).toHaveLength(0)
  })
})

